Persisting a job description (using MongoDB directly, or a dedicated
queue library like BullMQ - this lesson shows the underlying concept
directly first):

interface Job {
  _id: string;
  type: 'send-welcome-email' | 'generate-invoice-pdf';
  payload: Record<string, unknown>;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  createdAt: Date;
}

// The route handler - accepts work, persists it, returns IMMEDIATELY,
// directly extending Module 22 lesson 6's exact 202 Accepted pattern
app.post('/signup', async (req, res, next) => {
  try {
    const user = await createUser(req.body);

    await jobsCollection.insertOne({
      type: 'send-welcome-email',
      payload: { userId: user._id, email: user.email },
      status: 'pending',
      createdAt: new Date()
    });

    res.status(201).json({ success: true, data: { userId: user._id } });
    // returns IMMEDIATELY - the user does NOT wait for the actual
    // email send (lesson 1's measured 1,800ms) at all
  } catch (err) {
    next(err);
  }
});

// The WORKER - an entirely separate, independently-running process,
// continuously polling for pending work
async function workerLoop() {
  while (true) {
    const job = await jobsCollection.findOneAndUpdate(
      { status: 'pending' },
      { $set: { status: 'processing' } },
      { sort: { createdAt: 1 } }
    );

    if (job) {
      await performJob(job);
    } else {
      await sleep(1000); // no pending work right now - wait briefly,
                            // then check again
    }
  }
}

