async function performJob(job: Job) {
  try {
    switch (job.type) {
      case 'send-welcome-email':
        await emailProvider.send({
          to: job.payload.email as string,
          template: 'welcome'
        });
        break;
      case 'generate-invoice-pdf':
        const pdfBuffer = await generateInvoicePdf(job.payload);
        await uploadToS3(pdfBuffer, `invoices/${job.payload.invoiceId}.pdf`);
        break;
    }

    await jobsCollection.updateOne(
      { _id: job._id },
      { $set: { status: 'completed', completedAt: new Date() } }
    );
  } catch (err) {
    // The job genuinely failed - record this explicitly, rather than
    // letting it silently vanish or remain stuck in 'processing'
    // forever, which would make this failure genuinely invisible
    await jobsCollection.updateOne(
      { _id: job._id },
      { $set: { status: 'failed', error: (err as Error).message, failedAt: new Date() } }
    );
    console.error(`Job ${job._id} failed:`, err);
    // lesson 4 will build the genuine RETRY logic this catch block
    // currently lacks - for now, this job simply, visibly fails
  }
}

