import { Queue, Worker } from 'bullmq';

const emailQueue = new Queue('email-jobs', { connection: { url: process.env.REDIS_URL } });

app.post('/signup', async (req, res, next) => {
  try {
    const user = await createUser(req.body);

    await emailQueue.add('send-welcome-email', {
      userId: user._id,
      email: user.email
    });
    // BullMQ persists this job durably in Redis AND notifies any
    // currently-waiting worker immediately - no polling sleep at all

    res.status(201).json({ success: true, data: { userId: user._id } });
  } catch (err) {
    next(err);
  }
});

// The worker - directly replacing lesson 2's manual workerLoop
const emailWorker = new Worker('email-jobs', async (job) => {
  await emailProvider.send({ to: job.data.email, template: 'welcome' });
  // returning normally here = BullMQ automatically marks this job
  // complete; throwing an error = BullMQ automatically marks it
  // failed and (lesson 4's territory) can automatically retry it
}, { connection: { url: process.env.REDIS_URL } });

