// NON-IDEMPOTENT - genuinely dangerous if BullMQ's at-least-once
// guarantee ever redelivers this exact job
const paymentWorker = new Worker('payment-jobs', async (job) => {
  await paymentProvider.charge({
    amount: job.data.amount,
    cardToken: job.data.cardToken
  });
  // If this job is EVER redelivered (the worker crashed right after
  // this line, before BullMQ recorded completion), the customer's
  // card would genuinely be charged a SECOND time
});

// IDEMPOTENT - safe even if redelivered, directly using a unique
// idempotency key, exactly the pattern real payment providers expose
const paymentWorker = new Worker('payment-jobs', async (job) => {
  const existingCharge = await chargesCollection.findOne({ idempotencyKey: job.data.orderId });
  if (existingCharge) {
    return; // this EXACT charge has already genuinely succeeded -
              // safely, correctly do nothing on a redelivery
  }

  const charge = await paymentProvider.charge({
    amount: job.data.amount,
    cardToken: job.data.cardToken,
    idempotencyKey: job.data.orderId // many real payment providers
      // (Stripe, for instance) accept this directly, refusing to
      // create a SECOND genuine charge for the same key even if
      // this exact API call is itself made more than once
  });

  await chargesCollection.insertOne({ idempotencyKey: job.data.orderId, chargeId: charge.id });
});

