Retry logic with exponential backoff, directly extending lesson 2's performJob:

async function withRetry<T>(
  operation: () => Promise<T>,
  maxAttempts: number = 4
): Promise<T> {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (err) {
      if (attempt === maxAttempts) throw err; // genuinely exhausted
        // every attempt - let this final failure propagate

      const delayMs = Math.pow(2, attempt) * 1000; // 2s, 4s, 8s, 16s -
        // each retry waits LONGER than the last, exactly this lesson's
        // exponential-backoff principle
      console.log(`Attempt ${attempt} failed, retrying in ${delayMs}ms`);
      await sleep(delayMs);
    }
  }
  throw new Error('Unreachable');
}

// Applied directly to lesson 2's email-sending job
const emailWorker = new Worker('email-jobs', async (job) => {
  await withRetry(() => emailProvider.send({ to: job.data.email, template: 'welcome' }));
}, { connection: { url: process.env.REDIS_URL } });

