class CircuitBreaker {
  private failureCount = 0;
  private state: 'closed' | 'open' | 'half-open' = 'closed';
  private openedAt: number | null = null;

  constructor(
    private failureThreshold: number = 5,
    private cooldownMs: number = 30000
  ) {}

  async execute<T>(operation: () => Promise<T>): Promise<T> {
    if (this.state === 'open') {
      const elapsedSinceOpen = Date.now() - (this.openedAt ?? 0);
      if (elapsedSinceOpen < this.cooldownMs) {
        // The circuit is OPEN and the cooldown hasn't elapsed yet -
        // fail IMMEDIATELY, locally, without even attempting the real
        // call, giving the struggling dependency genuine relief
        throw new Error('Circuit breaker is open - failing fast');
      }
      this.state = 'half-open'; // cautiously allow exactly ONE
        // genuine attempt through, to test if recovery has happened
    }

    try {
      const result = await operation();
      this.failureCount = 0;
      this.state = 'closed'; // a genuine success - fully reset
      return result;
    } catch (err) {
      this.failureCount++;
      if (this.failureCount >= this.failureThreshold) {
        this.state = 'open';
        this.openedAt = Date.now();
      }
      throw err;
    }
  }
}

const emailCircuitBreaker = new CircuitBreaker();

const emailWorker = new Worker('email-jobs', async (job) => {
  await emailCircuitBreaker.execute(() =>
    withRetry(() => emailProvider.send({ to: job.data.email, template: 'welcome' }))
  ); // retry handles TRANSIENT failures within a single call's own
     // attempts; the circuit breaker handles SUSTAINED failure across
     // MANY calls over time - genuinely different timescales, working together
}, { connection: { url: process.env.REDIS_URL } });

