async function withRetry<T>(operation: () => Promise<T>, maxAttempts: number = 3): Promise<T> {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      const delayMs = Math.pow(2, attempt) * 1000;
      await sleep(delayMs);
    }
  }
  throw new Error('Unreachable');
}

class CircuitBreaker {
  private failureCount = 0;
  private state: 'closed' | 'open' | 'half-open' = 'closed';
  private openedAt: number | null = null;

  constructor(private failureThreshold: number = 4, private cooldownMs: number = 20000) {}

  async execute<T>(operation: () => Promise<T>): Promise<T> {
    if (this.state === 'open') {
      if (Date.now() - (this.openedAt ?? 0) < this.cooldownMs) {
        throw new Error('Circuit breaker is open - failing fast');
      }
      this.state = 'half-open';
    }

    try {
      const result = await operation();
      this.failureCount = 0;
      this.state = 'closed';
      return result;
    } catch (err) {
      this.failureCount++;
      if (this.failureCount >= this.failureThreshold) {
        this.state = 'open';
        this.openedAt = Date.now();
      }
      throw err;
    }
  }
}

const smsCircuitBreaker = new CircuitBreaker(4, 20000);

async function sendSms(phoneNumber: string, message: string) {
  return smsCircuitBreaker.execute(() =>
    withRetry(() => smsProvider.send({ to: phoneNumber, message }))
  );
}

