Publishing an event when something genuinely happens, directly extending lesson 3's BullMQ usage to a genuine pub/sub pattern:

import { Queue } from 'bullmq';

const eventBus = new Queue('order-events', { connection: { url: process.env.REDIS_URL } });

app.post('/orders', async (req, res, next) => {
  try {
    const order = await createOrder(req.body);

    // Publish ONE event - the publisher has NO idea how many
    // subscribers exist, or what any of them will actually do
    await eventBus.add('order-placed', { orderId: order._id, userId: order.userId, total: order.total });

    res.status(201).json({ success: true, data: order });
  } catch (err) {
    next(err);
  }
});

// SUBSCRIBER 1 - inventory system, genuinely independent
const inventoryWorker = new Worker('order-events', async (job) => {
  if (job.name !== 'order-placed') return;
  await decrementInventory(job.data.orderId);
}, { connection: { url: process.env.REDIS_URL } });

// SUBSCRIBER 2 - analytics system, genuinely independent, added
// LATER without ANY change to the original /orders route at all
const analyticsWorker = new Worker('order-events', async (job) => {
  if (job.name !== 'order-placed') return;
  await recordOrderMetric(job.data.total);
}, { connection: { url: process.env.REDIS_URL } });

