// DIRECT CALLS - the order service must know about, and directly
// call, EVERY system that needs to react - genuinely tightly coupled
async function placeOrderDirectCalls(orderData: OrderData) {
  const order = await createOrder(orderData);
  await inventoryService.decrementStock(order.items); // direct call 1
  await emailService.sendConfirmation(order.userId);    // direct call 2
  await analyticsService.recordOrder(order.total);      // direct call 3
  // Adding a FOURTH system later requires modifying THIS exact
  // function directly - genuine coupling, exactly the cost this
  // lesson's mentalModel described
  return order;
}

// EVENT-DRIVEN - the order service publishes ONE event and is
// completely DONE; it has zero knowledge of what reacts to it
async function placeOrderEventDriven(orderData: OrderData) {
  const order = await createOrder(orderData);
  await eventBus.add('order-placed', { orderId: order._id, userId: order.userId, total: order.total, items: order.items });
  // A fourth, fifth, or twentieth subscriber can be added LATER with
  // ZERO changes to this function - genuinely loose coupling
  return order;
}

// THE GENUINE TRADEOFF: event-driven decoupling is worth its added
// complexity (a message broker, eventual consistency between
// subscribers reacting at slightly different times, Module 27 lesson
// 1's exact consistency question) specifically when MULTIPLE,
// genuinely independent systems need to react to the SAME event, and
// that SET of reacting systems is expected to genuinely GROW over
// time. For a simple, two-step process that will never genuinely
// need a third reactor, direct calls remain simpler and entirely appropriate

