  const alreadyNotified = await fulfillmentLog.findOne({ orderId: job.data.orderId });
  if (alreadyNotified) return; // idempotency (lesson 3) - safe on redelivery

  await fulfillmentCircuitBreaker.execute(() =>
    withRetry(() => fulfillmentApi.notifyNewOrder(job.data)) // fault
      // tolerance (lesson 4) - retries handle transient failure,
      // the circuit breaker protects against the warehouse API
      // genuinely struggling under sustained, overwhelming load
